#include <deque>
#include <algorithm>
#include <iterator>

int main() {
    std::deque<int> d = {3, 1, 4, 1, 5, 9};

    // Random access allows iterator arithmetic
    auto it = d.begin();
    it += 3; // O(1) jump

    // Random access allows using std::sort
    std::sort(d.begin(), d.end());

    // Verify iterator category (C++11/17 way)
    using IterCat = typename std::iterator_traits<decltype(d.begin())>::iterator_category;
    // IterCat should be std::random_access_iterator_tag
}
